#!/usr/bin/env node
/**
 * node-bundle.mjs — build `hardsoftwebgpu-node.mjs`: the whole lab in one Node
 * file, with no repository around it and no dependencies.
 *
 *   node tools/node-bundle.mjs [--out hardsoftwebgpu-node.mjs]
 *
 * What goes in:
 *   * every module under src/ (the simulation, the GUI, the renderers, the
 *     trainer) plus index.html and the two WGSL shaders
 *   * tools/node-launcher.js — the server, the terminal dashboard and the
 *     acceptance / training modes
 *
 * At run time the generated file writes that tree into a temp directory (cached
 * by content hash, so repeat runs are instant) and hands control to the
 * launcher. Nothing is fetched; the browser app is served from the extracted
 * copy, and `--terminal` / `--all` / `--train` import the modules directly.
 */

import { readdir, readFile, writeFile } from 'node:fs/promises';
import { createHash } from 'node:crypto';
import { existsSync } from 'node:fs';
import { join, resolve, relative, posix, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const HERE = fileURLToPath(new URL('.', import.meta.url));
const REPO = resolve(HERE, '..');
const args = process.argv.slice(2);
const outArg = args.indexOf('--out');
const OUT = resolve(REPO, outArg >= 0 && args[outArg + 1] ? args[outArg + 1] : 'hardsoftwebgpu-node.mjs');

/** Collect every file the app needs, keyed by repo-relative POSIX path. */
async function collect(dir, filter) {
  const files = {};
  for (const entry of await readdir(dir, { withFileTypes: true })) {
    const full = join(dir, entry.name);
    if (entry.isDirectory()) Object.assign(files, await collect(full, filter));
    else if (filter(entry.name)) {
      files[posix.join(...relative(REPO, full).split(/[\\/]/))] = await readFile(full, 'utf8');
    }
  }
  return files;
}

const files = {
  'index.html': await readFile(join(REPO, 'index.html'), 'utf8'),
  ...(await collect(join(REPO, 'src'), (n) => n.endsWith('.js') || n.endsWith('.wgsl'))),
  'tools/node-launcher.js': await readFile(join(REPO, 'tools/node-launcher.js'), 'utf8'),
};
// Node needs a module type marker for the extracted .js files; the launcher would
// otherwise be parsed as CommonJS and every `import` would fail.
files['package.json'] = '{\n  "name": "hardsoftwebgpu-standalone",\n  "private": true,\n  "type": "module"\n}\n';

for (const required of ['index.html', 'src/app/main.js', 'src/engine/robot.js', 'tools/node-launcher.js']) {
  if (!files[required]) throw new Error(`node-bundle: missing ${required}`);
}

const hash = createHash('sha1')
  .update(Object.keys(files).sort().join('\n'))
  .update(String(Object.values(files).reduce((a, s) => a + s.length, 0)))
  .digest('hex')
  .slice(0, 10);

const header = `#!/usr/bin/env node
/**
 * hardsoftwebgpu-node.mjs — Hard-Soft Arm Lab, single file, zero dependencies.
 *
 * Generated by tools/node-bundle.mjs from the repository at hash ${hash}.
 * Do not edit by hand; edit the sources and rebuild.
 *
 *   node hardsoftwebgpu-node.mjs                 serve the app (http://localhost:5173)
 *   node hardsoftwebgpu-node.mjs --open          serve and open a browser
 *   node hardsoftwebgpu-node.mjs --terminal      run the simulation in the terminal
 *   node hardsoftwebgpu-node.mjs --all           run all five jobs, print a table
 *   node hardsoftwebgpu-node.mjs --train         train both networks, print scores
 *   node hardsoftwebgpu-node.mjs --selftest      acceptance + training smoke test
 *   node hardsoftwebgpu-node.mjs --help
 *
 * ${Object.keys(files).length} files embedded · ${(JSON.stringify(files).length / 1024).toFixed(0)} kB payload
 */

import { mkdirSync, writeFileSync, existsSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { tmpdir } from 'node:os';
import { pathToFileURL } from 'node:url';

const FILES = __FILES__;
const HASH = ${JSON.stringify(hash)};
const ROOT = join(tmpdir(), 'hardsoftwebgpu-' + HASH);

function extract() {
  if (existsSync(join(ROOT, 'index.html'))) return ROOT;   // cached from a previous run
  for (const [rel, text] of Object.entries(FILES)) {
    const full = join(ROOT, rel);
    mkdirSync(dirname(full), { recursive: true });
    writeFileSync(full, text);
  }
  return ROOT;
}

const args = process.argv.slice(2);
if (args.includes('--help') || args.includes('-h')) {
  console.log(\`Hard-Soft Arm Lab — single-file Node build (hash \${HASH})

  node \${process.argv[1].split(/[\\\\/]/).pop()}                  serve on http://localhost:5173
                       --open            also open a browser window
                       --port 8080       use another port
                       --terminal        run the simulation in this terminal
                       --task N          pick job 1..5 (terminal mode)
                       --seconds S       episode length (terminal mode)
                       --all             acceptance suite for all five jobs
                       --train           train the IK network + transformer
                       --mlp-epochs N    training budget (default 60)
                       --policy-epochs N training budget (default 12)
                       --selftest        acceptance + training smoke test
  \`);
  process.exit(0);
}

const root = extract();
const launcher = await import(pathToFileURL(join(root, 'tools/node-launcher.js')).href);
await launcher.main({ root, args, label: 'Hard-Soft Arm Lab — single-file Node build' });
if (!args.includes('--terminal') && !args.includes('--all') && !args.includes('--train')
    && !args.includes('--selftest') && !args.includes('--headless')) {
  console.log('  (press ctrl-c to stop)');
}
`;

const body = header.replace('__FILES__', () => JSON.stringify(files));
if (body.includes('__FILES__')) throw new Error('node-bundle: placeholder not substituted');
await writeFile(OUT, body);
console.log(`wrote ${relative(REPO, OUT)} · ${(body.length / 1024).toFixed(0)} kB · ${Object.keys(files).length} files embedded · hash ${hash}`);
